// PF Config: the one place for all settings of the Participant follow-up workflows.
// Change values here only. The same workflow runs on staging and production (promoted by CI),
// so the mode comes from the instance this run is on:
//   darwin-production.app.n8n.cloud -> 'pilot' (real participants, only the hosts in pilotHostEmails)
//   anything else (staging)         -> 'mock'  (test addresses only, short timings, [MOCK] tag)

const PRODUCTION_HOST = 'darwin-production.app.n8n.cloud';
const STAGING_HOST = 'darwin-staging.app.n8n.cloud';

const base = {
  // Pilot: only these hosts get the follow-up on production. Empty list = all hosts (release).
  pilotHostEmails: ['aniol.moner@n8n.io'],
  pilotUnavailableText: 'Rewards through Darwin are in a pilot and not available for you yet. For now, please keep using `/reward`.',

  // Mock mode guard (staging): sends go only to these addresses.
  allowedParticipantEmailPattern: '^aniol\\.moner\\+[^@]+@n8n\\.io$',
  // aniol.moner+nohost@ has no Slack user: it tests the host-not-in-Slack branch on staging.
  allowedHostEmails: ['aniol.moner@n8n.io', 'aniol.moner+nohost@n8n.io'],

  // Person who gets the Tremendous refill DM.
  adminEmail: 'aniol.moner@n8n.io',

  // Store: Supabase calendar_research_sessions (credential "Supabase Postgres").
  // dataTableId is the old mock table, still used by PF Reset Mock Data until it is switched.
  dataTableName: 'MOCK - PF Sessions',
  dataTableId: 'L3Sa3FfY5RtqeUgk',

  // Calendly
  // Continuous discovery = bookings for this one event type, and nothing else:
  // https://calendly.com/d/dz6d-wr6-6bf/research-with-n8n
  cdEventTypeUuid: 'ebd64db8-7c09-4e31-bc2e-339065fbb930',
  roundRobinEventTypeUuid: 'ebd64db8-7c09-4e31-bc2e-339065fbb930', // old name, used by PF Calendly Capture
  uxrUtmSource: 'uxr_recruiting',

  // Timing (real)
  timezone: 'Europe/Madrid',
  askDelayMinutes: 15,
  showupWindowHours: 6,
  finalTimeoutMinutes: 24 * 60,
  manualLookbackDays: 30,

  // Reward
  rewardDefaultUsd: 50,
  rewardMaxUsd: 100,
  currency: 'USD',
  // Tremendous mode is set per instance in buildConfig: live on production, stub everywhere else.
  tremendousCampaignId: 'NRF2R8ZSE9XK',
  tremendousFundingSourceId: 'balance',
  balanceThresholdUsd: 500,
  mockBalanceUsd: 900,

  // Slack questions: false = links in the text (no interactivity needed); true = native buttons.
  // Buttons need the pf_ route in UXR Interaction Handler and PF Button Router (both live since 2026-10-27).
  slackButtons: true,

  // Email
  emailFrom: 'n8n Research <noreply@info.n8n.io>',
  emailReplyTo: 'design@n8n.io',
};

// Short delays on staging, so a full test takes minutes, not hours.
const mockOverrides = {
  askDelayMinutes: 1,
  finalTimeoutMinutes: 3,
};

function detectEnvironment() {
  const url = String($execution.resumeUrl || '');
  const host = (url.match(/^https?:\/\/([^/:]+)/) || [])[1] || '';
  if (host === PRODUCTION_HOST) return 'production';
  if (host === STAGING_HOST) return 'staging';
  return 'unknown';
}

function buildConfig(environment) {
  // Only production runs the pilot. Staging and unknown hosts stay in mock mode (the safe side).
  const mockMode = environment !== 'production';
  const config = mockMode ? { ...base, ...mockOverrides } : { ...base };
  config.environment = environment;
  config.mode = mockMode ? 'mock' : 'pilot';
  config.mockMode = mockMode;
  // The one host list every workflow checks. Empty = all hosts.
  config.hostAllowList = (mockMode ? base.allowedHostEmails : base.pilotHostEmails).map((e) => e.toLowerCase());
  // Real orders only on production (credential Tremendous Production). Mock mode never pays real money.
  config.tremendousMode = mockMode ? 'stub' : 'live';
  return config;
}

const environment = detectEnvironment();
const config = buildConfig(environment);

// Manual Test Run only: also show the production values. Sub-workflow calls never get this.
let manualRun = false;
try { manualRun = $('Manual Test Run').isExecuted === true; } catch (e) { manualRun = false; }
if (manualRun) {
  return [{ json: { ...config, simulated_production: buildConfig('production') } }];
}
return [{ json: config }];
